package com.Senai.Mubak.service; import org.springframework.stereotype.Service; import java.security.*; import java.nio.charset.StandardCharsets; import java.util.HexFormat; @Service public class SenhaService {public String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}